def _process(self, sym, resolved_scales, input_symbols=frozenset()):
    """Recursively replace Sqrt/Power of varying bases with RegPower."""
    if not sym.children:
        return sym

    new_children = [
        self._process(child, resolved_scales, input_symbols)
        for child in sym.children
    ]

    if isinstance(sym, pybamm.Sqrt):
        regularised = self._regularise(
            new_children[0], 0.5, resolved_scales, input_symbols
        )
        if regularised is not None:
            return regularised
    elif isinstance(sym, pybamm.Power):
        regularised = self._regularise(
            new_children[0], new_children[1], resolved_scales, input_symbols
        )
        if regularised is not None:
            return regularised

    if any(n is not o for n, o in zip(new_children, sym.children, strict=True)):
        return sym.create_copy(new_children=new_children)
    return sym

def _regularise(self, base, exponent, resolved_scales, input_symbols):
    """
    Return the regularised version of ``base ** exponent``, or None if the
    power should be kept as it is (i.e. evaluated exactly).
    """
    if not self._varies(base, input_symbols):
        # The base is fixed by the parameter values, so the power is a
        # well-defined constant with no derivative to stabilise. Keep it
        # exact: regularising it would change its value by an arbitrary
        # factor, since the base can be of any magnitude.
        return None

    scale = self._get_scale(base, resolved_scales)
    if scale is None:
        scale = self._infer_scale(base, resolved_scales, input_symbols)
    return pybamm.RegPower(base, exponent, scale=scale)

@classmethod
def _varies(cls, expr, input_symbols):
    """
    Whether an expression can vary while the model is being solved, i.e. it
    depends on one of the function inputs or on the solution itself.
    """
    for node in expr.pre_order():
        if node in input_symbols:
            return True
        if not node.children and not isinstance(node, cls._STATIC_LEAVES):
            # e.g. a variable, a state vector, time or a spatial variable
            return True
    return False

def _infer_scale(self, base, resolved_scales, input_symbols):
    """
    Derive the scale of a base that is a product (or quotient) of scaled
    symbols and state-independent factors, e.g. ``k * c_e`` has scale
    ``|k| * c_e_scale``. Returns None if no scale can be derived, in which
    case the default scale (1) is used.
    """
    numerator, denominator = [], []
    # Each entry is a factor of the base, together with whether it
    # multiplies (True) or divides (False) the base.
    factors = [(base, True)]
    while factors:
        expr, multiplies = factors.pop()
        if isinstance(expr, pybamm.Negate):
            # the sign does not affect the scale
            factors.append((expr.child, multiplies))
        elif not self._varies(expr, input_symbols):
            # a state-independent factor sets the magnitude of the base
            (numerator if multiplies else denominator).append(
                pybamm.simplify_if_constant(pybamm.AbsoluteValue(expr))
            )
        elif isinstance(expr, pybamm.Multiplication):
            factors.append((expr.left, multiplies))
            factors.append((expr.right, multiplies))
        elif isinstance(expr, pybamm.Division):
            factors.append((expr.left, multiplies))
            factors.append((expr.right, not multiplies))
        else:
            # a varying factor: its scale has to be known
            scale = self._get_scale(expr, resolved_scales)
            if scale is None:
                return None
            (numerator if multiplies else denominator).append(scale)

    if not numerator and not denominator:
        return None  # pragma: no cover

    scale = None
    for factor in numerator:
        scale = factor if scale is None else scale * factor
    for factor in denominator:
        scale = 1 / factor if scale is None else scale / factor

    # Guard against a zero scale (a zero state-independent factor makes the
    # whole base zero), which would otherwise give 0 / 0.
    return pybamm.simplify_if_constant(
        pybamm.Maximum(scale, pybamm.Scalar(self._MIN_SCALE))
    )

def _get_scale(self, expr, resolved_scales):
    """Get scale for an expression, defaulting to None.

    Only exact matches are used. For patterns like (c_max - c_s),
    they must be explicitly registered in the scales dict.
    """
    for var, scale in resolved_scales.items():
        if expr == var:
            return scale
    return None

